<?php require 'config.php'; require_role('student'); $title='Academic Progress'; $u=$_SESSION['user'];
$terms=get_terms($pdo); $allCompleted=0; $totalUnits=0; foreach($terms as $t){$q=$pdo->prepare("SELECT COALESCE(SUM(s.units),0) FROM academic_records ar JOIN subjects s ON s.id=ar.subject_id WHERE ar.user_id=? AND ar.term_id=? AND ar.remarks IN ('Passed','Completed')");$q->execute([$u['id'],$t['id']]);$allCompleted+=(int)$q->fetchColumn();}
$q=$pdo->prepare("SELECT COALESCE(SUM(s.units),0) FROM enrollments e JOIN subjects s ON s.id=e.subject_id WHERE e.student_id=? AND e.status='approved'");$q->execute([$u['id']]);$currentUnits=(int)$q->fetchColumn(); $totalUnits=max(150,$allCompleted+$currentUnits);
$percent=$totalUnits?min(100,round(($allCompleted/$totalUnits)*100)):0;
require 'header.php'; ?>
<section class="section"><div class="section-intro"><div><span class="eyebrow">ACADEMIC</span><h2>Academic Progress</h2><p class="muted">A simple overview of completed and current academic units.</p></div><a class="btn subtle-btn" href="grades.php">View Grades</a></div>
<div class="progress-card"><div class="progress-summary"><div><span>Completed Units</span><strong><?=$allCompleted?></strong></div><div><span>Current Enrolled Units</span><strong><?=$currentUnits?></strong></div><div><span>Progress</span><strong><?=$percent?>%</strong></div></div><div class="progress-track"><span style="width:<?=$percent?>%"></span></div><p class="muted">Prototype target: 150 total units. Progress is calculated from recorded passed/completed subjects.</p></div>
<div class="section-grid-2"><div class="card"><div class="card-head"><h3>Academic Terms</h3></div><?php foreach($terms as $t):?><div class="list-row"><span><b><?=e($t['label'])?></b><small><?=((int)$t['is_current']===1?'Current term':'Previous term')?></small></span><a class="small-link" href="academic_records.php?term=<?=e($t['term_key'])?>">Records →</a></div><?php endforeach;?></div><div class="card"><div class="card-head"><h3>Next Steps</h3></div><div class="reminder-row"><span class="reminder-mark">1</span><span><b>Review your grades</b><small>Check posted grades and remarks.</small></span></div><div class="reminder-row"><span class="reminder-mark">2</span><span><b>Check your schedule</b><small>Keep your class times and rooms updated.</small></span></div><div class="reminder-row"><span class="reminder-mark">3</span><span><b>Complete pending enrollment</b><small>Review requests that still need action.</small></span></div></div></div></section><?php require 'footer.php'; ?>
